/**
 * Typed catalog loaders. Pure functions over `content/catalog.json` (generated by `npm run catalog`), validated with
 * Zod on first use. Safe to call from Server Components, route handlers and `generateStaticParams`.
 */
import rawCatalog from "@/content/catalog.json";
import { CatalogFileSchema, type CatalogFile } from "./schema";
import { normaliseCatalog, slugify, foldText } from "./normalise";
import type { Catalog, Genre, Title, TitleType } from "./types";

let cache: Catalog | null = null;

/** Parse and normalise a catalog file. Exported for tests; the app uses `getCatalog()`. */
export function loadCatalog(input: unknown): Catalog {
  const parsed = CatalogFileSchema.safeParse(input);
  if (!parsed.success) {
    throw new Error(`content/catalog.json failed validation:\n${formatIssues(parsed.error.issues)}`);
  }
  return normaliseCatalog(parsed.data as CatalogFile);
}

export function getCatalog(): Catalog {
  cache ??= loadCatalog(rawCatalog);
  return cache;
}

function formatIssues(issues: { path: PropertyKey[]; message: string }[]): string {
  return issues
    .slice(0, 20)
    .map((i) => `  - ${i.path.map(String).join(".") || "(root)"}: ${i.message}`)
    .join("\n");
}

// ---------------------------------------------------------------------------------------------------------------
// Loaders
// ---------------------------------------------------------------------------------------------------------------

export function getTitles(filter: { type?: TitleType } = {}, catalog = getCatalog()): Title[] {
  return filter.type ? catalog.titles.filter((t) => t.type === filter.type) : catalog.titles;
}

export function getTitleBySlug(slug: string, catalog = getCatalog()): Title | undefined {
  return catalog.titles.find((t) => t.slug === slug);
}

export function getGenres(catalog = getCatalog()): Genre[] {
  return catalog.genres;
}

export function getGenre(slug: string, catalog = getCatalog()): Genre | undefined {
  return catalog.genres.find((g) => g.slug === slug);
}

export function getByGenre(genreSlug: string, catalog = getCatalog()): Title[] {
  return catalog.titles.filter((t) => t.genres.some((g) => g.slug === genreSlug));
}

/** Editorially curated "trending" order, then the rest by year (newest first). AFTERLIGHT has no audience data. */
export function getTrending(limit = 12, catalog = getCatalog()): Title[] {
  const curated = catalog.editorial.trending
    .map((slug) => catalog.titles.find((t) => t.slug === slug))
    .filter((t): t is Title => Boolean(t));
  const rest = catalog.titles.filter((t) => !curated.includes(t)).sort((a, b) => b.year - a.year);
  return [...curated, ...rest].slice(0, limit);
}

/** Hero rotation: editorial picks, falling back to the first titles. */
export function getHeroTitles(limit = 5, catalog = getCatalog()): Title[] {
  const picks = catalog.editorial.hero
    .map((slug) => catalog.titles.find((t) => t.slug === slug))
    .filter((t): t is Title => Boolean(t));
  return (picks.length ? picks : catalog.titles).slice(0, limit);
}

export function getCollections(catalog = getCatalog()) {
  return catalog.collections;
}

/**
 * Case- and accent-insensitive search over title, tagline, genres and credits. Ranked: title prefix > title word >
 * title contains > genre/credit > synopsis.
 */
export function search(query: string, catalog = getCatalog()): Title[] {
  const q = foldText(query).trim();
  if (q.length < 1) return [];
  const scored: { title: Title; score: number }[] = [];
  for (const title of catalog.titles) {
    const name = foldText(title.title);
    let score = 0;
    if (name.startsWith(q)) score = 100;
    else if (name.split(/\s+/).some((w) => w.startsWith(q))) score = 80;
    else if (name.includes(q)) score = 60;
    else if (title.genres.some((g) => foldText(g.name).includes(q))) score = 40;
    else if (allPeople(title).some((p) => foldText(p.name).includes(q))) score = 35;
    else if (title.tagline && foldText(title.tagline).includes(q)) score = 20;
    else if (foldText(title.synopsis).includes(q)) score = 10;
    if (score) scored.push({ title, score });
  }
  return scored.sort((a, b) => b.score - a.score || b.title.year - a.title.year).map((s) => s.title);
}

/** Titles sharing the most genres with `slug` (same type first), excluding itself. */
export function related(slug: string, limit = 8, catalog = getCatalog()): Title[] {
  const source = getTitleBySlug(slug, catalog);
  if (!source) return [];
  const genres = new Set(source.genres.map((g) => g.slug));
  return catalog.titles
    .filter((t) => t.slug !== slug)
    .map((t) => ({
      t,
      score: t.genres.filter((g) => genres.has(g.slug)).length * 10 + (t.type === source.type ? 1 : 0),
    }))
    .filter((x) => x.score >= 10)
    .sort((a, b) => b.score - a.score || b.t.year - a.t.year)
    .slice(0, limit)
    .map((x) => x.t);
}

export function getLicences(catalog = getCatalog()) {
  return catalog.licences;
}

export { routes } from "./routes";

function allPeople(t: Title) {
  return [...t.credits.directors, ...t.credits.cast, ...t.credits.writers];
}

export { slugify };
